<div class="d-flex justify-content-between align-items-center mb-3"><div><h1 class="h3">Reports</h1><p class="text-secondary mb-0">Operational stock, sales, ledger and cash reports.</p></div></div>
<div class="card shadow-sm"><div class="card-body"><div class="row g-2 mb-3"><div class="col-md-4"><select id="type" class="form-select"><option value="stock">Stock Summary</option><option value="sold">Cylinders Sold</option><option value="sales">Sales History</option><option value="receipts">Receipt History</option><option value="payments">Payment History</option><option value="balances">Customer Outstanding</option><option value="supplier_balances">Supplier Outstanding</option><option value="held">Cylinders Held by Customer</option><option value="cash">Daily Cash Register</option><option value="expenses">Expenses</option></select></div><div class="col-md-2"><input id="from" type="date" class="form-control" value="<?=e(date('Y-m-d'))?>"></div><div class="col-md-2"><input id="to" type="date" class="form-control" value="<?=e(date('Y-m-d'))?>"></div><div class="col-md-2"><button id="load" class="btn btn-primary w-100">Run</button></div><div class="col-md-2"><button id="csv" class="btn btn-outline-secondary w-100">CSV</button></div></div><div class="table-responsive"><table class="table table-sm" id="t"><thead></thead><tbody></tbody></table></div></div></div>
<script>
$(function(){const b=<?=json_encode(url('/'),JSON_THROW_ON_ERROR)?>;function load(){const q={type:$('#type').val(),from:$('#from').val(),to:$('#to').val()};$.getJSON(b+'reports/data',q).done(r=>{let rows=r.data.rows||[],h=$('#t thead').empty(),body=$('#t tbody').empty();if(!rows.length){body.html('<tr><td>No data</td></tr>');return;}Object.keys(rows[0]).forEach(k=>h.append('<th>'+k.replaceAll('_',' ')+'</th>'));rows.forEach(v=>{let tr='<tr>';Object.values(v).forEach(x=>tr+='<td>'+String(x??'')+'</td>');tr+='</tr>';body.append(tr)})}).fail(x=>alert(x.responseJSON?.message||'Report failed'))}$('#load').click(load);$('#csv').click(()=>window.open(b+'reports/csv?type='+encodeURIComponent($('#type').val())+'&from='+$('#from').val()+'&to='+$('#to').val(),'_blank'));load()});
</script>